import json
g=[r[:] for r in G['Test input']]
def fill(g):
    seen=set()
    out=[r[:] for r in g]
    # process each color separately: flood-fill connected component bbox
    for c in [2,8,3,1]:
        for i,r in enumerate(g):
            for j,v in enumerate(r):
                if v==c and (i,j) not in seen:
                    stack=[(i,j)]; comps=[]
                    while stack:
                        a,b=stack.pop()
                        if (a,b) in seen: continue
                        seen.add((a,b))
                        comps.append((a,b)); out[a][b]=c
                        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                            na,nb=a+da,b+db
                            if 0<=na<len(g) and 0<=nb<len(g[0]) and g[na][nb]==c and (na,nb) not in seen:
                                stack.append((na,nb))
                    ms=min(a for a,b in comps); Ms=max(a for a,b in comps)
                    ns=min(b for a,b in comps); Ns=max(b for a,b in comps)
                    for a in range(ms,Ms+1):
                        for b in range(ns,Ns+1):
                            out[a][b]=c
    return out
res=fill(g)
for r in res: print(''.join(map(str,r)))
print(json.dumps(res))

